#!/usr/bin/env node
/**
 * Tests for hooks/lib/secret-read.js and hooks/lib/docker-cp.js, through hooks/guard-shell.js (their
 * only caller). Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Half the cases are the reads that must stay silent: documentation (`.env.example`), a search
 * pattern that merely looks like a file name, a `find` without `-exec`.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir, homedir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'guard-shell.js');
const cwd = mkdtempSync(join(tmpdir(), 'secret-'));
process.on('exit', () => { try { rmSync(cwd, { recursive: true, force: true }); } catch { /* tmp */ } });

function run(command, tool_name = 'Bash') {
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ tool_name, tool_input: { command }, cwd }), encoding: 'utf8',
  });
  assert.equal(r.status, 0, 'the hook must always exit 0');
  if (!r.stdout.trim()) return { decision: 'approve', reason: '' };
  const out = JSON.parse(r.stdout).hookSpecificOutput;
  return { decision: out.permissionDecision, reason: out.permissionDecisionReason ?? '' };
}

test('a shell read of a secret file is denied, whatever the reader', () => {
  const denied = [
    'Get-Content .env', 'gc ./.env.local', 'type .env.production', 'cat ~/.ssh/id_rsa', 'cat keys/server.pem',
    'Get-Content -Path D:\\profile\\.claude.json', 'Select-String -Pattern token -Path .env', 'grep KEY .env',
    'head -n 3 ~/.azure-work/msal_token_cache.json', 'cat ~/.config/gh/hosts.yml', 'cat ~/.docker/config.json',
    'cat ~/.git-credentials', 'tail cert.pfx', 'Get-Content ~/.claude/.credentials.json',
    'find . -name .env -exec cat {} +', 'find . -name "*.pem" -exec cat {} \\;',
  ];
  for (const command of denied) {
    const r = run(command);
    assert.equal(r.decision, 'deny', command);
    assert.match(r.reason, /secret-bearing file/, command);
  }
});

test('a secret read hidden in a shell wrapper or a chain is denied too', () => {
  assert.equal(run('bash -c "cat .env"').decision, 'deny');
  assert.equal(run('pwsh -NoProfile -c "Get-Content ~/.config/gh/hosts.yml"').decision, 'deny');
  assert.equal(run('echo go && cat .env').decision, 'deny');
  assert.equal(run('Get-Content .env', 'PowerShell').decision, 'deny');
});

test('documentation, search patterns and look-alikes stay readable', () => {
  const quiet = [
    'Get-Content .env.example', 'cat .env.template', 'cat README.md', 'Get-Content appsettings.json',
    'grep -rn "\\.pem" src', 'grep "\\.env" docs/setup.md', 'Select-String -Pattern pem -Path a.txt',
    'find . -name .env', 'git log -p', 'ls .env', 'cat .envrc.md',
  ];
  for (const command of quiet) assert.equal(run(command).decision, 'approve', command);
});

test('docker cp onto the host outside the cwd or under ~/.claude asks; inside the cwd or into a container passes', () => {
  const absolute = join(homedir(), '.claude', 'hooks', 'x.js').replaceAll(String.fromCharCode(92), '/');
  const claude = run(`docker cp api:/app/x.js ${absolute}`);
  assert.equal(claude.decision, 'ask');
  assert.match(claude.reason, /Confirm\?$/);
  assert.equal(run('docker cp api:/app/x.js ~/.claude/hooks/x.js').decision, 'ask');
  assert.equal(run('docker cp api:/var/log/a.log /etc/cron.d/a').decision, 'ask');
  assert.equal(run('docker cp api:/var/log/a.log ../elsewhere/a.log').decision, 'ask');
  assert.equal(run('docker cp api:/var/log/a.log ./out/a.log').decision, 'approve');
  assert.equal(run('docker cp api:/var/log/a.log a.log').decision, 'approve');
  assert.equal(run('docker cp ./seed.sql db:/tmp/seed.sql').decision, 'approve', 'into a container');
  assert.equal(run('docker ps').decision, 'approve');
});
